function Get-FlatTabs {
  $resp=Invoke-WebRequest -UseBasicParsing -Uri ("http://127.0.0.1:$RemoteDebuggingPort/json/list") -TimeoutSec 3
  $obj=$resp.Content|ConvertFrom-Json
  $flat=@();if($obj -is [System.Array]){foreach($x in $obj){$flat+=$x}}elseif($null -ne $obj){$flat+=$obj};return $flat
}
function Receive-Cdp([System.Net.WebSockets.ClientWebSocket]$Ws,[int]$Seconds){$buf=New-Object byte[] 65536;$ms=New-Object IO.MemoryStream;$cts=New-Object Threading.CancellationTokenSource;$cts.CancelAfter([Math]::Max(1000,$Seconds*1000));try{do{$seg=New-Object ArraySegment[byte] -ArgumentList @(,$buf);try{$res=$Ws.ReceiveAsync($seg,$cts.Token).GetAwaiter().GetResult()}catch{throw 'CDP_RECEIVE_TIMEOUT_OR_CLOSED'};if($res.MessageType -eq [System.Net.WebSockets.WebSocketMessageType]::Close){throw 'CDP_WEBSOCKET_CLOSED'};$ms.Write($buf,0,$res.Count)}while(-not $res.EndOfMessage);return [Text.Encoding]::UTF8.GetString($ms.ToArray())|ConvertFrom-Json}finally{$cts.Dispose();$ms.Dispose()}}
function Send-Cdp([System.Net.WebSockets.ClientWebSocket]$Ws,[ref]$Seq,[string]$Method,[hashtable]$Params=@{}){$Seq.Value++;$id=$Seq.Value;$json=@{id=$id;method=$Method;params=$Params}|ConvertTo-Json -Depth 30 -Compress;$bytes=[Text.Encoding]::UTF8.GetBytes($json);$seg=New-Object ArraySegment[byte] -ArgumentList @(,$bytes);$cts=New-Object Threading.CancellationTokenSource;$cts.CancelAfter([Math]::Max(1000,$CdpCommandTimeoutSeconds*1000));try{$Ws.SendAsync($seg,[System.Net.WebSockets.WebSocketMessageType]::Text,$true,$cts.Token).GetAwaiter().GetResult()}catch{throw ('CDP_SEND_TIMEOUT '+$Method)}finally{$cts.Dispose()};while($true){$msg=Receive-Cdp $Ws $CdpCommandTimeoutSeconds;if($msg.id -eq $id){if($msg.error){throw ('CDP_'+$Method+': '+($msg.error|ConvertTo-Json -Compress))};return $msg.result}}}
function Eval-Cdp($Ws,[ref]$Seq,[string]$Expr){$r=Send-Cdp $Ws $Seq 'Runtime.evaluate' @{expression=$Expr;returnByValue=$true;awaitPromise=$true;userGesture=$true};return $r.result.value}
function Click-Cdp($Ws,[ref]$Seq,[double]$X,[double]$Y){[void](Send-Cdp $Ws $Seq 'Input.dispatchMouseEvent' @{type='mouseMoved';x=$X;y=$Y});[void](Send-Cdp $Ws $Seq 'Input.dispatchMouseEvent' @{type='mousePressed';x=$X;y=$Y;button='left';clickCount=1});Start-Sleep -Milliseconds 100;[void](Send-Cdp $Ws $Seq 'Input.dispatchMouseEvent' @{type='mouseReleased';x=$X;y=$Y;button='left';clickCount=1})}
function Connect-Page($Tab){$ws=New-Object System.Net.WebSockets.ClientWebSocket;$cts=New-Object Threading.CancellationTokenSource;$cts.CancelAfter([Math]::Max(1000,$CdpCommandTimeoutSeconds*1000));try{$ws.ConnectAsync([Uri]([string]$Tab.webSocketDebuggerUrl),$cts.Token).GetAwaiter().GetResult()}catch{$ws.Dispose();throw 'CDP_CONNECT_TIMEOUT_OR_FAILED'}finally{$cts.Dispose()};return $ws}
$result=[ordered]@{ok=$false;action='NOTEBOOKLM_EXACT_FRESH_SOURCE_BIND_CDP_V5';startedAt=(Get-Date).ToString('o');targetNotebookUrl=$TargetNotebookUrl;notebookUrl='';notebookId=$TargetNotebookId;sourceAdded=$false;sourceVerified=$false;promptFilled=$false;promptSubmitted=$false;studioSelected=$false;createdNotebook=$false;stage='START';error='';evidence=@{}}
$ws=$null
