  $result.stage='PAGE_CONNECT';$tabs=@(Get-FlatTabs|Where-Object{[string]$_.type -eq 'page'});if(-not $tabs){throw 'NO_CDP_PAGE_TARGET'};$tab=$tabs|Where-Object{[string]$_.url -like 'https://notebook.google.com/*'}|Select-Object -First 1;if(-not $tab){$tab=$tabs|Select-Object -First 1};$ws=Connect-Page $tab;$seq=0;[void](Send-Cdp $ws ([ref]$seq) 'Runtime.enable' @{});[void](Send-Cdp $ws ([ref]$seq) 'Page.enable' @{});[void](Send-Cdp $ws ([ref]$seq) 'Page.bringToFront' @{})
