  $pre=Eval-Cdp $ws ([ref]$seq) "(() => {const txt=document.body?.innerText||'';return {title:document.title,url:location.href,marker:txt.includes('NLM_FRESH_ALL_20260829_1915'),zero:/소스\s*0건|0\s*sources?/i.test(txt),one:/소스\s*[1-9][0-9]*건|[1-9][0-9]*\s*sources?/i.test(txt),sample:txt.slice(0,2200)}})()";$result.evidence.before=$pre;if($pre.marker -or $pre.one){$result.sourceAdded=$true;$result.sourceVerified=$true}
  if(-not $result.sourceVerified){
    $result.stage='SOURCE_TAB';$find="(() => {const vis=e=>{if(!(e instanceof HTMLElement))return false;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>2&&r.height>2&&s.display!=='none'&&s.visibility!=='hidden'};for(const e of [...document.querySelectorAll('[role=tab],button,[role=button],a')].filter(vis)){const raw=String([e.innerText,e.textContent,e.getAttribute('aria-label')].join(' ')).trim();const t=raw.toLowerCase();if(raw==='출처'||raw.startsWith('출처 ')||t==='sources'||t.startsWith('sources ')){const r=e.getBoundingClientRect();return {ok:true,x:r.left+r.width/2,y:r.top+r.height/2,text:raw}}}return {ok:false,sample:(document.body?.innerText||'').slice(0,1200)}})()";$x=Eval-Cdp $ws ([ref]$seq) $find;if(-not $x.ok){throw ('SOURCE_TAB_NOT_FOUND: '+[string]$x.sample)};Click-Cdp $ws ([ref]$seq) ([double]$x.x) ([double]$x.y);Start-Sleep -Milliseconds 800
    $result.stage='ADD_SOURCE';$find="(() => {const vis=e=>{if(!(e instanceof HTMLElement))return false;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>2&&r.height>2&&s.display!=='none'&&s.visibility!=='hidden'};const txt=document.body?.innerText||'';if(/복사한 텍스트|copied text|paste text/i.test(txt))return {ok:false,dialogOpen:true};for(const e of [...document.querySelectorAll('button,[role=button],a')].filter(vis)){const raw=String([e.innerText,e.textContent,e.getAttribute('aria-label'),e.getAttribute('title')].join(' '));const t=raw.toLowerCase();if(raw.includes('소스 추가')||t.includes('add source')){const r=e.getBoundingClientRect();return {ok:true,x:r.left+r.width/2,y:r.top+r.height/2,text:raw.slice(0,160)}}}return {ok:false,dialogOpen:false,sample:txt.slice(0,1400)}})()";$x=Eval-Cdp $ws ([ref]$seq) $find;if($x.ok){Click-Cdp $ws ([ref]$seq) ([double]$x.x) ([double]$x.y);Start-Sleep -Milliseconds 800}elseif(-not $x.dialogOpen){throw ('ADD_SOURCE_CONTROL_NOT_FOUND: '+[string]$x.sample)}
    $result.stage='PASTE_TYPE';$find="(() => {const vis=e=>{if(!(e instanceof HTMLElement))return false;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>2&&r.height>2&&s.display!=='none'&&s.visibility!=='hidden'};for(const e of [...document.querySelectorAll('button,[role=button],a,div[tabindex]')].filter(vis)){const raw=String([e.innerText,e.textContent,e.getAttribute('aria-label'),e.getAttribute('title')].join(' '));const t=raw.toLowerCase();if(raw.includes('복사한 텍스트')||raw.includes('텍스트 붙여넣기')||t.includes('copied text')||t.includes('paste text')){const r=e.getBoundingClientRect();return {ok:true,x:r.left+r.width/2,y:r.top+r.height/2,text:raw.slice(0,160)}}}return {ok:false,sample:(document.body?.innerText||'').slice(0,1600)}})()";$x=Eval-Cdp $ws ([ref]$seq) $find;if(-not $x.ok){throw ('COPIED_TEXT_CONTROL_NOT_FOUND: '+[string]$x.sample)};Click-Cdp $ws ([ref]$seq) ([double]$x.x) ([double]$x.y);Start-Sleep -Milliseconds 700
    $sourceJson=$SourceText|ConvertTo-Json -Compress;$result.stage='SOURCE_FILL';$fill="(() => {const vis=e=>{if(!(e instanceof HTMLElement))return false;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>2&&r.height>2&&s.display!=='none'&&s.visibility!=='hidden'};const dialogs=[...document.querySelectorAll('[role=dialog],mat-dialog-container,.mat-mdc-dialog-container')].filter(vis);const root=dialogs[dialogs.length-1]||document;const all=[...root.querySelectorAll('textarea,[contenteditable=true],input:not([type=hidden])')].filter(vis);const e=all.find(x=>x.tagName==='TEXTAREA')||all.find(x=>/텍스트|text|paste|붙여넣/i.test(String(x.getAttribute('placeholder')||'')))||all.find(x=>x.getAttribute('contenteditable')==='true');if(!e)return {ok:false,sample:(document.body?.innerText||'').slice(0,1600)};e.focus();if('value'in e){const p=e.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:HTMLInputElement.prototype;const s=Object.getOwnPropertyDescriptor(p,'value')?.set;if(s)s.call(e,$sourceJson);else e.value=$sourceJson;}else{e.textContent=$sourceJson;}e.dispatchEvent(new InputEvent('input',{bubbles:true,inputType:'insertText',data:$sourceJson}));e.dispatchEvent(new Event('change',{bubbles:true}));return {ok:true,len:('value'in e?e.value:e.textContent).length,placeholder:e.getAttribute('placeholder')||''}})()";$x=Eval-Cdp $ws ([ref]$seq) $fill;if(-not $x.ok){throw ('SOURCE_EDITOR_NOT_FOUND: '+[string]$x.sample)};$result.evidence.editor=$x
    $result.stage='SOURCE_SUBMIT';$find="(() => {const vis=e=>{if(!(e instanceof HTMLElement))return false;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>2&&r.height>2&&s.display!=='none'&&s.visibility!=='hidden'&&!e.disabled};const dialogs=[...document.querySelectorAll('[role=dialog],mat-dialog-container,.mat-mdc-dialog-container')].filter(vis);const root=dialogs[dialogs.length-1]||document;const exact=['삽입','추가','저장','insert','add','save'];for(const e of [...root.querySelectorAll('button,[role=button]')].filter(vis)){const raw=String([e.innerText,e.textContent,e.getAttribute('aria-label'),e.getAttribute('title')].join(' ')).trim();const t=raw.toLowerCase().replace(/\s+/g,' ');if(exact.some(w=>t===w||t.startsWith(w+' '))){const r=e.getBoundingClientRect();return {ok:true,x:r.left+r.width/2,y:r.top+r.height/2,text:raw.slice(0,160)}}}return {ok:false,sample:[...root.querySelectorAll('button,[role=button]')].map(e=>String([e.innerText,e.getAttribute('aria-label')].join(' ')).trim()).filter(Boolean).slice(-30)}})()";$x=Eval-Cdp $ws ([ref]$seq) $find;if(-not $x.ok){throw ('SOURCE_SUBMIT_NOT_FOUND: '+(($x.sample|ConvertTo-Json -Compress)))};Click-Cdp $ws ([ref]$seq) ([double]$x.x) ([double]$x.y);$result.sourceAdded=$true
    $deadline=(Get-Date).AddSeconds(35);do{Start-Sleep -Milliseconds 700;$v=Eval-Cdp $ws ([ref]$seq) "(() => {const txt=document.body?.innerText||'';return {zero:/소스\s*0건|0\s*sources?/i.test(txt),one:/소스\s*[1-9][0-9]*건|[1-9][0-9]*\s*sources?/i.test(txt),marker:txt.includes('NLM_FRESH_ALL_20260829_1915'),checks:[...document.querySelectorAll('input[type=checkbox],[role=checkbox],mat-checkbox')].length,sample:txt.slice(0,2200)}})()";if($v.marker -or $v.one -or (-not $v.zero -and $v.checks -gt 0)){$result.sourceVerified=$true;$result.evidence.sourceVerify=$v;break}}while((Get-Date)-lt $deadline);if(-not $result.sourceVerified){$result.evidence.sourceVerify=$v;throw 'SOURCE_ADD_NOT_VERIFIED'}
  }
  $result.stage='CHAT_PROMPT';$find="(() => {const vis=e=>{if(!(e instanceof HTMLElement))return false;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>2&&r.height>2&&s.display!=='none'&&s.visibility!=='hidden'};for(const e of [...document.querySelectorAll('[role=tab],button,[role=button],a')].filter(vis)){const raw=String([e.innerText,e.textContent,e.getAttribute('aria-label')].join(' ')).trim();if(raw==='채팅'||raw.toLowerCase()==='chat'){const r=e.getBoundingClientRect();return {ok:true,x:r.left+r.width/2,y:r.top+r.height/2}}}return {ok:false}})()";$x=Eval-Cdp $ws ([ref]$seq) $find;if($x.ok){Click-Cdp $ws ([ref]$seq) ([double]$x.x) ([double]$x.y);Start-Sleep -Milliseconds 600};$promptJson=$PromptText|ConvertTo-Json -Compress;$fill="(() => {const vis=e=>{if(!(e instanceof HTMLElement))return false;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>2&&r.height>2&&s.display!=='none'&&s.visibility!=='hidden'};const all=[...document.querySelectorAll('textarea,[contenteditable=true]')].filter(vis);const e=all.find(x=>/질문|창작|ask|create/i.test(String([x.getAttribute('placeholder'),x.getAttribute('aria-label')].join(' '))))||all[all.length-1];if(!e)return {ok:false};e.focus();if('value'in e){const p=e.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:HTMLInputElement.prototype;const s=Object.getOwnPropertyDescriptor(p,'value')?.set;if(s)s.call(e,$promptJson);else e.value=$promptJson;}else{e.textContent=$promptJson;}e.dispatchEvent(new InputEvent('input',{bubbles:true,inputType:'insertText',data:$promptJson}));e.dispatchEvent(new Event('change',{bubbles:true}));return {ok:true,len:('value'in e?e.value:e.textContent).length}})()";$x=Eval-Cdp $ws ([ref]$seq) $fill;$result.promptFilled=[bool]$x.ok;$result.evidence.prompt=$x
  if($result.promptFilled){$find="(() => {const vis=e=>{if(!(e instanceof HTMLElement))return false;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>2&&r.height>2&&s.display!=='none'&&s.visibility!=='hidden'&&!e.disabled};const els=[...document.querySelectorAll('button,[role=button]')].filter(vis);for(const e of els){const raw=String([e.innerText,e.textContent,e.getAttribute('aria-label'),e.getAttribute('title')].join(' ')).toLowerCase();if(/send|submit|전송|보내기|arrow_forward/.test(raw)){const r=e.getBoundingClientRect();return {ok:true,x:r.left+r.width/2,y:r.top+r.height/2}}}const cand=els.map(e=>({e,r:e.getBoundingClientRect()})).filter(x=>x.r.left>innerWidth*0.65&&x.r.top>innerHeight*0.55).sort((a,b)=>b.r.left-a.r.left)[0];if(cand)return {ok:true,x:cand.r.left+cand.r.width/2,y:cand.r.top+cand.r.height/2};return {ok:false}})()";$x=Eval-Cdp $ws ([ref]$seq) $find;if($x.ok){Click-Cdp $ws ([ref]$seq) ([double]$x.x) ([double]$x.y);$result.promptSubmitted=$true;Start-Sleep -Milliseconds 600}}
  $result.stage='STUDIO';$find="(() => {const vis=e=>{if(!(e instanceof HTMLElement))return false;const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>2&&r.height>2&&s.display!=='none'&&s.visibility!=='hidden'};for(const e of [...document.querySelectorAll('[role=tab],button,[role=button],a')].filter(vis)){const raw=String([e.innerText,e.textContent,e.getAttribute('aria-label')].join(' ')).trim();if(raw==='스튜디오'||raw.toLowerCase()==='studio'){const r=e.getBoundingClientRect();return {ok:true,x:r.left+r.width/2,y:r.top+r.height/2}}}return {ok:false}})()";$x=Eval-Cdp $ws ([ref]$seq) $find;if($x.ok){Click-Cdp $ws ([ref]$seq) ([double]$x.x) ([double]$x.y);$result.studioSelected=$true}
